    .my-button {
      padding: 12px 24px;
      background-color: #2563eb;
      color: white;
      border: none;
      border-radius: 6px;
      font-size: 16px;
      cursor: pointer;
    }

    .my-button:hover {
      background-color: #1d4ed8;
    }
  </style>
</head>
<body>

  <button class="my-button" onclick="handleClick()">
    Click me
  </button>

  <script>
    function handleClick() {
      alert("Button clicked!");
    }
  </script>

</body>
</html>
